'use strict';
(()=>{const M=window.MG,S=M.s,A=M.army,$=id=>document.getElementById(id),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),f=n=>Math.round(n).toLocaleString('de-DE'),B=(label,action,disabled=false)=>`<button class="btn" data-action="${e(action)}" ${disabled?'disabled':''}>${label}</button>`,select=(id,options,value)=>`<select class="select" id="${id}">${options.map(v=>{const [k,n]=Array.isArray(v)?v:[v,v];return `<option value="${e(k)}" ${String(k)===String(value)?'selected':''}>${e(n)}</option>`;}).join('')}</select>`,input=(id,value,min=0,max=100000)=>`<input class="select" id="${id}" type="number" value="${value}" min="${min}" max="${max}">`,check=(id,on,label)=>`<label class="check"><input type="checkbox" id="${id}" ${on?'checked':''}> ${label}</label>`,head=(name,sub)=>`<div class="pagehead"><div><p class="eyebrow">${e(S.schoolName)} · TAG ${S.day}</p><h1>${name}</h1><p>${sub}</p></div></div>`;
const modeOptions=[['current','Nach IST'],['potential','Nach SOLL'],['balanced','IST & SOLL ausgewogen']],priorities=[...modeOptions,['hero','Helden zuerst'],['elite','Eliteteam zuerst'],['talents','Talente fördern']],goals=[['current','Stärkstes Team'],['potential','Höchstes Potenzial'],['balanced','Ausgewogen'],['offensive','Offensiv'],['defensive','Defensiv'],['ranged','Fernkampf-lastig'],['melee','Nahkampf-lastig'],['talents','Talente fördern']];let scoutClass='all',scoutWeapon='all';let teamOpen=false;let difficultyBand=null,pageNo=0,query='',order='combat',filter='all',origin='all',teamFilter='all',hospitalBand='all',lastRecruits=[],benchSide=0,benchOffset=0,workPage=0;
const render=()=>M.ui.render(),notify=t=>M.ui.notify(t),modal=(title,body,buttons='')=>M.ui.modal(title,body,buttons),persist=()=>M.persist();
function pager(total){const pages=Math.max(1,Math.ceil(total/20));pageNo=Math.min(pageNo,pages-1);return `<div class="toolbar">${B('Zurück','army:page:-1',pageNo===0)}<span>${total} Einträge · Seite ${pageNo+1}/${pages}</span>${B('Weiter','army:page:1',pageNo+1>=pages)}</div>`;}
function controls(){return `<details class="box"><summary>Klassen & Ausrüstung automatisch zuweisen</summary><p>Optional. Gesperrte Entscheidungen bleiben erhalten.</p><div class="toolbar"><label>Bewertung ${select('armyMode',modeOptions,S.army.mode)}</label>${B('KLASSEN AUTOMATISCH ZUWEISEN','army:classes')}<label>Ausrüstung ${select('armyEquipPriority',priorities,S.army.equipPriority||'balanced')}</label>${B('ALLE AUTOMATISCH AUSRÜSTEN','army:equipall')}${B('AKTIVES TEAM AUSRÜSTEN','army:equipteam')}</div></details>`;}
function recruitPage(){const cfg=S.army.recruit;return head('Blind rekrutieren','100 Gold pro unbekanntem Rekruten. Name, Herkunft, Werte und Potenziale werden erst nach dem Kauf erzeugt und sichtbar.')+`<section class="box"><h2>${f(S.gold)} Gold · ${S.roster.length} Gladiatoren</h2><div class="toolbar"><label>Anzahl ${input('armyRecruitCount',1,1,Math.floor(S.gold/100))}</label>${B('REKRUTIEREN · 100 G PRO PERSON','army:recruit',S.gold<100)}${B('10 REKRUTIEREN · 1.000 G','army:recruit10',S.gold<1000)}${B('ZUM TALENTSCOUT','nav:scout')}</div><p>Keine Vorschau, keine Qualitätsklassen beim Kauf. Auch Massenkäufe nutzen dieselbe Zufallsverteilung.</p></section>${recruitRules()}${lastRecruits.length?`<section class="box"><h2>Gerade aufgenommen · ${lastRecruits.length}</h2>${lastRecruits.slice(0,20).map(id=>{const g=S.roster.find(g=>g.id===id);return g?`<div class="list-row"><span>${e(g.name)}<small>${e(M.scout(g).recommended)} · höchstes SOLL ${M.scout(g).overall.toFixed(1)}</small></span>${B('Profil','detail:'+id)}</div>`:'';}).join('')}${lastRecruits.length>20?'<p>Alle weiteren Rekruten stehen im Talentscout.</p>':''}</section>`:''}`;}
function recruitRules(){const c=S.army.recruit;return `<details class="box"><summary>Automatische Rekrutierung · ${c.enabled?'aktiv':'aus'}</summary><div class="form-grid">${check('armyRecruitEnabled',c.enabled,'Beim nächsten Tageswechsel rekrutieren')}<label>Höchstens pro Tag ${input('armyRecruitPerDay',c.perDay,0,1000)}</label><label>Goldreserve mindestens ${input('armyRecruitMinGold',c.minGold)}</label><label>Zielgröße des Kaders ${input('armyRecruitTarget',c.target,1)}</label><label>Reserve auffüllen bis (0 = kein Reservelimit) ${input('armyRecruitReserves',c.reserves)}</label></div><p>Es gelten alle eingestellten Grenzen zugleich. Kein Kauf zwischen Tageswechseln.</p></details>`;}
function scoutRows(roster=false){let gs=S.roster.filter(g=>!query||(g.name+' '+g.origin+' '+g.role).toLowerCase().includes(query.toLowerCase())).filter(g=>origin==='all'||g.origin===origin).filter(g=>teamFilter==='all'||teamFilter==='none'?! (teamFilter==='none'&&S.teams.some(t=>t.includes(g.id))):S.teams[+teamFilter]?.includes(g.id));
 gs=gs.filter(g=>filter==='all'||filter==='healthy'&&A.ready(g,true)||filter==='injured'&&!A.ready(g,true)||filter==='reserve'&&g.reserve||filter==='unused'&&!S.teams.some(t=>t.includes(g.id))||filter==='offspring'&&!!g.parents||filter==='father'&&(A.bestWeapon(g,false,true).value>=80||M.scout(g).overall>=75)||g.role===filter||(!roster&&M.roles.includes(filter)));
 if(roster)gs=gs.filter(g=>scoutClass==='all'||g.role===scoutClass);const score=g=>{if(order==='combat'||order==='current')return roster?M.combatValues(g).current:scoutValues(g).current;if(order==='combatCap'||order==='potential')return roster?M.combatValues(g).maximum:scoutValues(g).maximum;if(order.includes('|')){const [role,mode]=order.split('|');return A.rating(g,role,mode);}return {current:Math.max(...M.roles.map(r=>A.rating(g,r,'current'))),potential:M.scout(g).overall,weaponNow:Math.max(A.bestWeapon(g,false).value,A.bestWeapon(g,true).value),weaponCap:Math.max(A.bestWeapon(g,false,true).value,A.bestWeapon(g,true,true).value),bow:g.caps.weapons.bow,crossbow:g.caps.weapons.crossbow,age:g.age,wins:g.wins,losses:g.losses,kills:g.kills,experience:g.stats.experience,morale:g.stats.morale,value:M.marketValue(g)}[order]||0;};return gs.sort((a,b)=>score(b)-score(a)||a.name.localeCompare(b.name));}
function scoutWeapons(){return M.weaponDefs.filter(w=>scoutClass==='all'||(scoutClass==='Fernkämpfer'?['bow','crossbow'].includes(w.id):!w.ammo||M.allowedRanged({role:scoutClass},w.id)));}
function scoutValues(g){const roles=(scoutClass==='all'?M.roles:[scoutClass]).filter(role=>scoutWeapon==='all'||(role==='Fernkämpfer'?['bow','crossbow'].includes(scoutWeapon):!M.weaponDefs.find(w=>w.id===scoutWeapon)?.ammo||M.allowedRanged({role},scoutWeapon))),value=potential=>Math.max(...roles.map(role=>{const r=M.scoutScore(g,role,potential),v=potential?g.caps.weapons:g.mastery;return M.clamp(r.score+(scoutWeapon==='all'?0:((v[scoutWeapon]||1)-r.best.value)*.2),1,100);}));return {current:value(false),maximum:value(true)};}
function scoutLineup(gs){return `<section class="box"><h2>Aufstellung · ${gs.length} Gladiatoren</h2><p>Seitlich wischen. Antippen öffnet das Profil. Alle Klassen werden berücksichtigt, unabhängig von der Zuweisung. KW / SOLL-KW zeigen hier die IST-/SOLL-Eignung für die gewählte Klasse (1–100), ohne Ausrüstungsbonus. Eine gewählte Waffe ersetzt den besten Waffenwert in der Bewertung.</p><div class="scout-lineup" tabindex="0" aria-label="Gladiatoren seitlich durchblättern">${gs.map(g=>{const raw=scoutValues(g),v={current:raw.current.toFixed(1),maximum:raw.maximum.toFixed(1)};return `<button class="scout-figure" data-action="detail:${g.id}"><span>Zugewiesen: ${e(g.role)}</span><canvas data-scoutfigure="${g.id}" aria-label="${e(g.name)} in seiner Ausrüstung"></canvas><strong>${e(g.name)}</strong><b>${['combatCap','potential'].includes(order)?'SOLL-KW '+v.maximum:'KW '+v.current}</b><small>KW ${v.current} · SOLL-KW ${v.maximum}</small><small>Klasse IST ${A.rating(g,scoutClass==='all'?g.role:scoutClass,'current').toFixed(1)} / SOLL ${A.rating(g,scoutClass==='all'?g.role:scoutClass,'potential').toFixed(1)}</small>${scoutWeapon!=='all'?`<small>Waffe IST ${(g.mastery[scoutWeapon]||1).toFixed(1)} / SOLL ${g.caps.weapons[scoutWeapon]}</small>`:''}</button>`;}).join('')||'<p>Keine Gladiatoren für diese Filter.</p>'}</div></section>`;}
function scoutPage(){const gs=scoutRows();return head('Talentscout · IST & SOLL','Kämpfer vergleichen, Potenziale erkennen und das Profil direkt öffnen.')+`<section class="box"><div class="toolbar"><label>Bewerten als ${select('armyScoutClass',[['all','Alle Klassen'],...M.roles],scoutClass)}</label><label>Aufstellen nach ${select('armyOrder',[['combat','Kampfwert · IST'],['combatCap','Kampfwert · SOLL'],['current','Klassenwerte · IST'],['potential','Klassenwerte · SOLL']],order)}</label><label>Waffenbegabung bewerten ${select('armyScoutWeapon',[['all','Alle Waffen'],...scoutWeapons().map(w=>[w.id,w.name])],scoutWeapon)}</label>${B('Filter zurücksetzen','army:scoutreset')}</div></section>`+scoutLineup(gs)+`<details class="box"><summary>Alle IST-/SOLL-Werte & weitere Filter</summary>${scoutTable()}</details>`;}
function rosterOverview(){const gs=scoutRows(true);return head('Gladiatorenübersicht','Dein gesamter Kader. Profile und Ausrüstung mit einem Klick öffnen.', '')+`<div class="toolbar"><label>Klasse ${select('armyScoutClass',[['all','Alle Klassen'],...M.roles],scoutClass)}</label><label>Sortieren ${select('armyOrder',[['combat','Kampfwert · IST'],['combatCap','Kampfwert · SOLL'],['current','Talent · IST'],['potential','Talent · SOLL']],order)}</label>${B('Alle Filter zurücksetzen','army:scoutreset')}${B('ZUM TALENTSCOUT','nav:scout')}</div>${pager(gs.length)}<div class="grid">${gs.slice(pageNo*20,pageNo*20+20).map(g=>{const v=M.combatValues(g);return `<section class="box roster-person"><canvas data-scoutfigure="${g.id}"></canvas><div><h2>${e(g.name)}</h2><p>${e(g.role)} · ${e(g.origin)}<br>KW ${v.current} · SOLL-KW ${v.maximum}<br>Gesundheit ${Math.round(M.health(g))} %</p>${B('PROFIL ÖFFNEN','detail:'+g.id)}${B('AUSRÜSTEN','loadout:'+g.id)}</div></section>`;}).join('')||'<p>Keine Gladiatoren für diese Filter.</p>'}</div>`;}
function scoutTable(){const gs=scoutRows(),pg=pager(gs.length);return head('Talentscout & Kader','IST zeigt den erlernten Stand, SOLL das erreichbare Potenzial. Pro Klasse zählt die beste einzelne geeignete Waffengattung.')+controls()+`<details class="box"><summary>Klassenbewertung & Schnellfilter</summary><p>55 % passende Hauptwerte, 20 % beste Waffengattung, 15 % Manöver, 10 % Körperteilkraft und Beweglichkeit. Keine Mittelwert-Abwertung durch andere Waffen. Fernkampf: ausschließlich Bogen oder Armbrust.</p>${M.roles.map(r=>`<p><b>${r}:</b> ${M.classSpecs[r].plan}</p><div class="buttons">${B('Beste '+r,'army:quick:'+r+':current')}${B(r+'-Talente','army:quick:'+r+':potential')}</div>`).join('')}${B('Beste Reservisten','army:filter:reserve')}${B('Ungenutzte Talente','army:filter:unused')}${B('Nachwuchskandidaten','army:filter:father')}</details><div class="toolbar"><label>Suchen <input class="select" id="armyQuery" value="${e(query)}" placeholder="Name, Herkunft, Klasse"></label><label>Sortierung ${select('armyAdvancedOrder',[...modeOptions,['weaponNow','Beste Waffen-IST'],['weaponCap','Beste Waffen-SOLL'],['bow','Bogen SOLL'],['crossbow','Armbrust SOLL'],...M.roles.flatMap(r=>[[r+'|current',r+' IST'],[r+'|potential',r+' SOLL']]),['age','Alter'],['wins','Siege'],['losses','Niederlagen'],['kills','Kills'],['experience','Erfahrung'],['morale','Moral'],['value','Marktwert']],order)}</label><label>Filter ${select('armyFilter',[['all','Alle'],['healthy','Einsatzbereit'],['injured','Verletzt / erschöpft'],['reserve','Reservisten'],['unused','Ohne Team'],['offspring','Nachwuchs'],['father','Nachwuchskandidaten']],filter)}</label><label>Herkunft ${select('armyOrigin',[['all','Alle'],...M.origins],origin)}</label><label>Team ${select('armyTeamFilter',[['all','Alle'],['none','Ohne Team'],...S.teamPlans.map((p,i)=>[i,p.name])],teamFilter)}</label></div>${pg}<div class="army-table-wrap"><table class="army-table"><thead><tr><th>Gladiator</th>${M.roles.map(r=>`<th>${r}<br>IST / SOLL</th>`).join('')}<th>Beste Begabung · IST / SOLL</th><th>Kampfwert · aktuell / maximal</th><th>Verwaltung</th></tr></thead><tbody>${gs.slice(pageNo*20,pageNo*20+20).map(g=>{const v=A.eligibility(g),w=A.bestWeapon(g,g.role==='Fernkämpfer',true);return `<tr><td><b>${e(g.name)}</b><small>${e(g.origin)} · ${g.age} J.<br>${e(A.teamOf(g.id)||'Ohne Team')}<br>${g.role}${g.locks?.class?' 🔒':''} · ${v.ok?'einsatzbereit':e(v.causes.join(', '))}</small></td>${M.roles.map(r=>`<td>${A.rating(g,r,'current').toFixed(1)} / <b>${A.rating(g,r,'potential').toFixed(1)}</b></td>`).join('')}<td>${e(M.weaponDefs.find(d=>d.id===w.id).name)}<br>IST ${(g.mastery[w.id]||1).toFixed(1)} / SOLL ${w.value.toFixed(1)}</td><td>${scoutValues(g).current.toFixed(1)} / <b>${scoutValues(g).maximum.toFixed(1)}</b><small>Klassenbewertung · IST / SOLL</small></td><td>${B('Profil','detail:'+g.id)}${B('Verwalten','army:person:'+g.id)}${B('Ausrüstung','loadout:'+g.id)}</td></tr>`;}).join('')}</tbody></table></div>${pg}`;}
let troopSize=null,troopClass='all',troopQuery='',troopSlot=0;
const troopSizes=[1,2,3,5,10,15,20,30,50,75,100];
function teamPage(){
 troopSize??=A.plan()?.size||3;const index=S.teamPlans.findIndex(p=>p.size===troopSize);if(index>=0&&index!==S.teamIndex)A.activateTeam(index);
 return head('Truppenplatz','Größe wählen, Plätze antippen und Krieger zuweisen. Pro Größe gibt es genau eine Gruppe.')+`<div class="troop-sizes" role="group" aria-label="Gruppengröße">${troopSizes.map(n=>`<button class="btn ${troopSize===n?'primary':''}" data-action="army:troopsize:${n}" aria-pressed="${troopSize===n}">${n} gegen ${n}<small>${S.teamPlans.some(p=>p.size===n)?'Aufstellung':'Noch leer'}</small></button>`).join('')}</div>`+(index<0?`<section class="box empty"><h2>${troopSize}er-Gruppe anlegen</h2><p>Wähle danach deine Krieger direkt hier aus.</p>${B('GRUPPE ANLEGEN','army:newsize:'+troopSize)}</section>`:teamEditor());
}
function teamEditor(){const p=A.plan(),members=S.teams[S.teamIndex],choices=[['','Platz frei'],...S.roster.map(g=>[g.id,g.name+' · '+g.role])];troopSlot=Math.min(troopSlot,p.size-1);
 const positions=Array.from({length:p.size},(_,i)=>i),leaderPos=members.indexOf(p.leader);if(leaderPos>=0){positions.splice(positions.indexOf(leaderPos),1);positions.splice(Math.floor(p.size/2),0,leaderPos);}
 const pool=S.roster.filter(g=>!g.dead&&!g.retired&&(troopClass==='all'||g.role===troopClass)&&(!troopQuery||g.name.toLowerCase().includes(troopQuery.toLowerCase()))).sort((a,b)=>M.power(b)-M.power(a)),visible=pool.slice(pageNo*20,pageNo*20+20);
 return `<section class="box troop-plaza"><div class="toolbar"><label>Gruppenname <input class="select" id="armyTeamName" maxlength="40" value="${e(p.name)}"></label><span>${members.filter(Boolean).length} / ${p.size} Krieger</span>${B('GRUPPE LÖSCHEN','army:deleteteam')}</div><div class="lineup-scroll"><div class="team-lineup">${positions.map(i=>{const g=S.roster.find(g=>g.id===members[i]),hero=g&&p.leader===g.id;return `<div class="troop-position ${i===troopSlot?'selected':''}" data-troop-slot="${i}"><button class="lineup-fighter ${hero?'leader':''}" data-action="${g?'detail:'+g.id:'army:troopslot:'+i}">${g?`<span>${hero?'★ ANFÜHRER':e(g.role)}</span><canvas data-teamfigure="${g.id}" data-hero="${hero?'1':'0'}" data-pose="${i}"></canvas><strong>${e(g.name)}</strong><small>KW ${M.power(g)}</small>`:`<span>Platz ${i+1}</span><strong class="empty-figure">＋</strong><small>Krieger zuweisen</small>`}</button><div class="troop-slot-actions">${B(g?'Ersetzen':'Auswählen','army:troopslot:'+i)}${g?B('Ausrüsten','loadout:'+g.id)+B(hero?'★':'Anführer','army:troopleader:'+g.id)+B('Entfernen','army:troopremove:'+i):''}</div></div>`}).join('')}</div></div><p class="tiny">Figur antippen: Profil. Am Computer kannst du Krieger aus dem Kader auf einen Platz ziehen.</p></section>
 <section class="box"><h2>Krieger für Platz ${troopSlot+1}</h2><div class="toolbar"><label>Klasse ${select('troopClass',[['all','Alle Klassen'],...M.roles],troopClass)}</label><label>Name <input class="select" id="troopQuery" value="${e(troopQuery)}" placeholder="Krieger suchen"></label></div>${pager(pool.length)}<div class="troop-recruits">${visible.map(g=>`<button class="troop-recruit" draggable="true" data-troop-drag="${g.id}" data-action="army:troopadd:${g.id}" ${members.includes(g.id)?'disabled':''}><b>${e(g.name)}</b><small>${g.role} · KW ${M.power(g)} · ${Math.round(M.health(g))} % Gesundheit</small><span>${members.includes(g.id)?'In dieser Gruppe':'＋ Zuweisen'}</span></button>`).join('')||'<p>Keine passenden Krieger.</p>'}</div></section>
 <details class="box"><summary>Automatik & Ausrüstungsbedarf</summary><div class="toolbar"><label>Ziel ${select('armyTeamGoal',goals,p.goal||'balanced')}</label>${B('AUTOMATISCH AUFSTELLEN','army:autoteam')}${B('VERLETZTE ERSETZEN','army:replace')}${B('EINSATZBEREIT MACHEN','army:ready')}${B('AUSRÜSTUNG SPEICHERN','army:saveplan')}${B('AUSRÜSTUNG LADEN','army:restoreplan')}</div>${needsPanel()}</details><details class="box"><summary>Anführer, Taktik & Reservepool</summary><label>Anführer ${select('armyLeader',[['','Kein Anführer'],...M.selectedTeam().map(g=>[g.id,g.name+' · Führungswert '+A.heroValue(g).toFixed(1)])],p.leader||'')}</label>${check('armyLeaderLock',p.leaderLocked,'Anführer vor automatischem Teamwechsel schützen')}<p>Ein lebender Anführer gibt höchstens +5 Moral. Sein Tod kann die Moral um 4 senken.</p><div class="form-grid">${[['formation','Formation',['Eng','Normal','Breit']],['aggression','Aggressivität',['Defensiv','Ausgeglichen','Aggressiv']],['priority','Ziele',['Nächster Gegner','Schwächster Gegner','Stärkster Gegner','Fernkämpfer','Verletzter Gegner']],['ranged','Fernkampf',['Abstand halten','Normal','Aggressiv']],['help','Teamhilfe',['Niedrig','Normal','Hoch']]].map(([k,n,opts])=>`<label>${n} ${select('armyTactic-'+k,opts,S.tactics[k])}</label>`).join('')}</div><h3>Reservepool</h3><p>${p.reserves.map(id=>e(S.roster.find(g=>g.id===id)?.name||'')).join(' · ')||'Noch kein persönlicher Reservepool. Freie Kämpfer werden ersatzweise berücksichtigt.'}</p><div class="toolbar">${select('armyReserve',choices,'')}${B('RESERVE HINZUFÜGEN / ENTFERNEN','army:reserve')}</div></details>`;
}
function personDialog(id){const g=S.roster.find(g=>g.id===id);if(!g)return;A.person(g);modal('Verwalten · '+g.name,`<div class="form-grid"><label>Klasse ${select('armyPersonRole-'+id,M.roles,g.role)}</label>${check('armyAvailable-'+id,g.available,'Für Einsätze freigegeben')}${check('armyReserveFlag-'+id,g.reserve,'Als Reservist führen')}<label>Trainingswaffe ${select('armyTrain-'+id,M.weaponDefs.map(w=>[w.id,w.name]),g.trainingWeapon||'short')}</label></div><h3>Vor Automatik schützen</h3><div class="army-locks">${[['class','Klasse'],['team','Team & Position'],['training','Trainingsziel'],['availability','Einsatzstatus'],['reserve','Reservestatus'],['partner','Partnerwahl'],...A.slots.map(k=>[k,({weapon:'Fernwaffe',secondary:'Haupt-/Ersatzwaffe',shield:'Schild'})[k]||M.armorDefs.find(x=>x.id===k)?.name])].map(([k,n])=>check('armyLock-'+id+'-'+k,g.locks[k],n)).join('')}</div><p>Manuelle Änderungen sind auch bei einer Sperre möglich. Die Sperre schützt ausschließlich vor Automatik.</p>`,B('AUSRÜSTUNG ÖFFNEN','loadout:'+id));}
function hospitalPage(){const patients=S.roster.filter(g=>Object.values(g.body).some(p=>p.hp<100-p.chronic||p.missing||p.fracture||p.internal||p.bleed)||g.fatigue>0||g.blood<100).map(g=>({g,est:A.hospitalEstimate(g)})).filter(({est})=>hospitalBand==='all'||hospitalBand==='today'&&est.days===0||hospitalBand==='short'&&est.days>=1&&est.days<=3||hospitalBand==='week'&&est.days>=4&&est.days<=7||hospitalBand==='long'&&est.days>7).sort((a,b)=>b.est.days-a.est.days),pg=pager(patients.length);return head('Krankenhaus','Verletzungen, Genesung und Einsatzregeln an einem Ort. Behandlungen verbrauchen keine Spieltage.')+`<section class="box"><div class="toolbar">${select('armyHospitalBand',[['all','Alle Verletzten'],['today','Heute wieder bereit'],['short','1–3 Tage'],['week','4–7 Tage'],['long','Mehr als 7 Tage']],hospitalBand)}${B('ALLE BEHANDELN · MEDICUS','army:treatall')}${B('TEAM VERLETZTE ERSETZEN','army:replace')}${B('EINSATZREGELN','nav:automation')}</div><p>Genesungsdauer: Schätzung bei natürlicher Heilung und unverändertem Zustand. Dauerfolgen und Amputationen werden nicht als vollständige Heilung versprochen.</p></section>${pg}<div class="grid">${patients.slice(pageNo*20,pageNo*20+20).map(({g,est})=>`<section class="box"><h3>${e(g.name)}</h3><p>${e(A.teamOf(g.id)||'Reserve / ohne Team')} · ${Math.round(M.health(g))} % Gesundheit<br>${A.ready(g,true)?'Einsatzbereit':'Nicht einsatzbereit'} · ${est.days} Tage bis akute Genesung<br>${est.permanent?'Dauerfolgen verbleiben':'Vollständig genesen voraussichtlich Tag '+(S.day+est.days)}</p><ul>${Object.entries(g.body).filter(([id,p])=>p.hp<100-p.chronic||p.missing||p.fracture||p.internal||p.bleed).map(([id,p])=>`<li>${e(M.partName(id))}: ${e(p.missing?'Amputation':p.injury||'Verletzt')} · Grad ${M.injuryGrade(p)}${p.fracture?' · Bruch':''}</li>`).join('')}</ul>${[0,1,2,3].map(t=>B(['Natürlich','Medicus','Premium','Spezialbehandlung'][t]+' · '+f(M.medicalCost(g,t))+' G','treat:'+g.id+':'+t,S.gold<M.medicalCost(g,t))).join('')}${B('PROFIL','detail:'+g.id)}</section>`).join('')||'<p class="empty">Keine passenden Patienten.</p>'}</div>${pg}`;}
function automationPage(){const r=S.army.rules;return head('Automatik & Einsatzregeln','Alle Automatiken sind optional, einzeln schaltbar und respektieren deine Sperren.')+controls()+recruitRules()+`<section class="box"><h2>Beim nächsten Tageswechsel</h2><div class="form-grid">${[['classes','Klassen zuweisen'],['teams','Teams auffüllen / zusammenstellen'],['equipment','Ausrüstung verteilen'],['replacements','Verletzte ersetzen']].map(([k,n])=>check('armyAuto-'+k,S.army.auto[k],n)).join('')}</div></section><section class="box"><h2>Einsatzgrenzen</h2><div class="toolbar">${B('VORSICHTIG','army:rules:careful')}${B('NORMAL','army:rules:normal')}${B('AGGRESSIV','army:rules:aggressive')}</div><div class="form-grid">${[['health','Gesundheit mindestens'],['energy','Erholte Ausdauer mindestens'],['grade','Verletzungsgrad höchstens'],['bleed','Blutung höchstens']].map(([k,n])=>`<label>${n} ${input('armyRule-'+k,r[k],0,k==='grade'?5:100)}</label>`).join('')}${check('armyRule-fractures',r.fractures,'Knochenbrüche zulassen')}${check('armyRule-internal',r.internal,'Innere Verletzungen zulassen')}</div><h3>Diese Körperbereiche müssen unverletzt sein</h3><div class="army-locks">${M.parts.map(([id,name])=>check('armyBodyRule-'+id,(r.blockParts||[]).includes(id),name)).join('')}</div></section><section class="box"><h2>Letzte Automatikentscheidungen</h2><div class="history">${S.army.audit.slice(0,30).map(x=>`<p>Tag ${x.day}: ${e(x.message)}</p>`).join('')||'Noch keine Entscheidungen.'}</div></section>`;}
function armyArena(){const p=A.plan(),band=difficultyBand??Math.min(9,Math.floor((S.league*7+3)/5)),entries=S.army.challenges.filter(c=>c.size===p.size&&Math.floor((c.rank-1)/5)===band),problem=M.validateTeam('challenge');return head('Arena · 50 Schwierigkeitsstufen','Je höher die Stufe, desto stärker die Gegner und ihre Ausrüstung. Alle Stufen sind ohne Qualifikation wählbar. Verletzungen und Tod bleiben dauerhaft.')+`<section class="box"><div class="toolbar"><label>Dein Team ${select('armyTeam',S.teamPlans.map((p,i)=>[i,p.name+' · '+p.size+' gegen '+p.size]),S.teamIndex)}</label>${B('Team vorbereiten','army:ready')}${B('Aufstellung ändern','nav:team')}</div><p class="readiness ${problem?'warning':'ready'}">${e(problem||'✓ Team einsatzbereit')}</p></section><section class="box"><h2>Schwierigkeit auswählen</h2><div class="difficulty-bands">${Array.from({length:10},(_,i)=>`<button class="btn ${i===band?'selected':''}" data-action="army:difficulty:${i}" aria-pressed="${i===band}"><strong>${i*5+1}–${i*5+5}</strong><span>${A.challengeTier(i*5+1)}</span></button>`).join('')}</div><p class="tiny">Zur aktuellen Liga passen ungefähr die Stufen ${S.league*7+1}–${Math.min(50,S.league*7+7)}. Jede Stufe ist einmal pro Tag verfügbar; Gegnerwerte schwanken leicht.</p></section><div class="challenge-list">${entries.map(c=>`<section class="box challenge-card"><div class="difficulty-number">${c.rank}<small>STUFE</small></div><div><span class="tag">${c.size} GEGEN ${c.size} · ${e(M.leagues[c.league].name)}</span><h2>${e(c.name)}</h2><p>${e(c.style)} · ${c.rank<S.league*7+1?'Unter deiner Liga':c.rank>S.league*7+7?'Über deiner Liga':'Im Bereich deiner Liga'}</p></div><div class="prize"><span>Einsatz <b>${f(c.fee)} G</b></span><span>Siegprämie <b>${f(c.reward)} G</b></span><small>Nach Einsatz: +${f(c.reward-c.fee)} G</small>${B(c.used?'Heute absolviert':'Kampf auswählen','army:challenge:'+c.id,c.used||S.gold<c.fee)}</div></section>`).join('')}</div><details class="box"><summary>Ligakampf & laufendes Turnier</summary><p>${e(M.leagues[S.fightLeague??S.league].name)} · ${p.size} gegen ${p.size}</p>${B('Ligakampf starten','army:leaguefight')}${S.tournament?B('Turnier fortsetzen','nexttournament'):''}${S.tournament?.type==='qualification'?B('Qualifikation abbrechen','cancelqualification'):''}${B('Liga ansehen','nav:league')}${S.lastReport?B('Letzter Kampfbericht','nav:report'):''}</details>`;}

function offspringPage(){const cs=S.children.filter(c=>!c.decision),pg=pager(cs.length);return head('Nachwuchstalente','Die Familienzeit ist spielerisch verkürzt: Nachwuchs erscheint als erwachsener, sofort ausbildbarer Rekrut. Abstammung und Vererbung bleiben gespeichert.')+`<div class="toolbar">${B('PARTNERSCHAFTEN','nav:household')}${B('KANDIDATEN IM SCOUT','army:filter:father')}</div>${pg}<div class="grid">${cs.slice(pageNo*20,pageNo*20+20).map(c=>{const g=c.template;return `<section class="box"><h2>${e(c.name)}</h2><p>${e(c.sex==='male'?'Sohn':'Tochter')} von ${e(c.parents.father.name)} und ${e(c.parents.mother.name)}</p>${M.roles.map(r=>`<p>${r}: IST ${A.rating(g,r,'current').toFixed(1)} / SOLL ${A.rating(g,r,'potential').toFixed(1)}</p>`).join('')}<p>Beste Waffenbegabung: ${e(M.weaponDefs.find(w=>w.id===A.bestWeapon(g,false,true).id).name)} ${A.bestWeapon(g,false,true).value.toFixed(1)}</p>${B('PROFIL','army:childprofile:'+c.id)}${c.sex==='male'?B('AUSBILDEN · 1.000 G','educate:'+c.id+':yes',S.gold<1000):'<p>Freier Lebensweg außerhalb der Arena.</p>'}${B('NICHT AUSBILDEN','educatedialog:'+c.id)}</section>`;}).join('')||'<p class="empty">Noch kein Nachwuchstalent verfügbar. Bestehende Partnerschaften werden ausschließlich beim Tageswechsel simuliert.</p>'}</div>${pg}`;}
function workshopPage(){return M.workshopPage?.()||head('Schmiede','Die Werkstatt wird geladen.');}
function ammoPanel(){return `<details class="box"><summary>Sammelaktionen · ${S.inventory.length} Gegenstände</summary><div class="toolbar">${B('TEAM AUSRÜSTEN','army:equipteam')}${B('ALLE AUSRÜSTEN','army:equipall')}${B('MASSENKAUF','army:bulkgear')}</div><p class="tiny">Pfeile und Bolzen stehen in jedem Kampf automatisch kostenlos bereit.</p></details>`;}
function dayReport(){const r=S.army.dayReport;modal('Tag '+S.day,`<p>${r.healed.length} genesen: ${e(r.healed.join(', ')||'–')}</p><p>${r.recruited.length} neue Rekruten · ${r.offspring.length} Nachwuchstalente</p><p>Waffentraining: +${r.training.toFixed(3)} insgesamt · ${r.challenges} gegnerische Teams aktualisiert</p><p>Sold für den aktuellen Kader: ${r.sold} Gold pro Tag. Erholung, Alter, Moral und Familienentwicklung wurden für genau einen Tag fortgeschrieben.</p>`,B('KRANKENHAUS','nav:medic')+B('NACHWUCHS','nav:offspring')+B('TALENTSCOUT','nav:scout'));}
function ensureBench(){const c=M.benchmarkConfig;c.entries??=[[],[]];c.teamTactics??=[M.copy(S.tactics),M.copy(S.tactics)];c.leaderIndices??=[-1,-1];for(const t of [0,1]){c['count'+t]??=c.count;for(let i=0;i<100;i++)c.entries[t][i]??={role:M.roles[i%3],weapon:'class',armor:'auto',shield:'auto',quality:2};}return c;}
function benchmarkBreakdown(r){const label=k=>M.moveNames[k]||(k.startsWith('shoot:')?'Schuss · ':k.startsWith('throw:')?'Wurf · ':'')+(M.weaponDefs.find(w=>w.id===k.split(':')[1])?.name||k);return `<div class="benchmark-breakdown">${r.teams.map((team,t)=>`<details class="box" open><summary>${t?'Team Rot':'Team Blau'} · Schaden nach Klassen</summary><div class="table-scroll"><table><thead><tr><th>Klasse</th><th>Krieger</th><th>Schaden</th><th>Erlitten</th><th>Kills</th></tr></thead><tbody>${(team.classes||[]).map(c=>`<tr><td>${e(c.role)}</td><td>${c.count}</td><td>${Math.round(c.damage)}</td><td>${Math.round(c.taken)}</td><td>${c.kills}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Kombos: ${(team.combos||[]).map(c=>c.length+'er: '+c.count).join(' · ')||'Keine Aufzeichnung'}</p><details open><summary>Alle ausgeführten Attacken</summary><div class="table-scroll"><table><thead><tr><th>Attacke</th><th>Einsätze</th><th>Treffer</th><th>Schaden</th></tr></thead><tbody>${(team.attackRows||[]).map(a=>`<tr><td>${e(label(a.key))}</td><td>${a.count}</td><td>${a.hits}</td><td>${a.damage.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><p class="tiny">Sandtritt: Ein Treffer blendet, verursacht aber keinen direkten Schaden. Durchstiche werden als eigener Treffer gezählt, ohne den Stichschaden doppelt zu zählen. Verfehlte oder abgewehrte Attacken zählen als Einsatz mit 0 Schaden. Ansturm wird zusätzlich zur Schlagtechnik gezählt; sein Schaden wird nur einmal zugeordnet. Flächenschläge können mehrere Treffer erzielen.</p></details></details>`).join('')}</div>`;}
function benchmarkPage(){const c=ensureBench(),t=benchSide,entries=c.entries[t],tactics=c.teamTactics[t];return head('Testschlachten · eigene Zusammenstellungen','Unabhängige Durchschnittskämpfer mit 50 / 50 in allen Werten. Keine Änderungen am Kader, Gold, Material oder Spieltag.')+`<section class="box"><div class="toolbar">${B('TEAM BLAU','army:benchside:0')}${B('TEAM ROT','army:benchside:1')}<label>Anzahl ${select('armyBenchCount',Array.from({length:100},(_,i)=>[i+1,(i+1)+' Kämpfer']),c['count'+t])}</label><label>Startwert ${input('armyBenchSeed',c.seed,1,4294967295)}</label><label>Arena ${select('armyBenchLeague',M.leagues.map((l,i)=>[i,l.name]),c.league)}</label></div><div class="toolbar"><label>Soldaten ${input('armyBenchSoldiers',Math.ceil(c['count'+t]/2),0,100)}</label><label>Assassinen ${input('armyBenchAssassins',Math.floor(c['count'+t]/4),0,100)}</label><label>Fernkämpfer ${input('armyBenchRanged',c['count'+t]-Math.ceil(c['count'+t]/2)-Math.floor(c['count'+t]/4),0,100)}</label>${B('VERTEILUNG ÜBERNEHMEN','army:benchmix')}</div><div class="toolbar"><label>Anführer ${select('armyBenchLeader',[[-1,'Kein Anführer'],...Array.from({length:c['count'+t]},(_,i)=>[i,'Kämpfer '+(i+1)])],c.leaderIndices[t])}</label>${[['formation',['Eng','Normal','Breit']],['aggression',['Defensiv','Ausgeglichen','Aggressiv']],['priority',['Nächster Gegner','Schwächster Gegner','Fernkämpfer','Verletzter Gegner']],['ranged',['Abstand halten','Normal','Aggressiv']],['help',['Niedrig','Normal','Hoch']]].map(([k,opts])=>`<label>${({formation:'Formation',aggression:'Aggressivität',priority:'Ziel',ranged:'Distanz',help:'Teamhilfe'})[k]} ${select('armyBenchTactic-'+k,opts,tactics[k])}</label>`).join('')}</div></section><div class="toolbar">${B("VORHERIGE 20","army:benchpage:-1",benchOffset===0)}<span>${benchOffset+1}–${Math.min(c["count"+t],benchOffset+20)} / ${c["count"+t]}</span>${B("NÄCHSTE 20","army:benchpage:1",benchOffset+20>=c["count"+t])}</div><div class="grid">${entries.map((a,i)=>({a,i})).slice(benchOffset,Math.min(c['count'+t],benchOffset+20)).map(({a,i})=>`<details class="box"><summary>${t?'Rot':'Blau'} ${i+1} · ${a.role} · ${a.weapon==='class'?'Klassenwaffe':e(M.weaponDefs.find(w=>w.id===a.weapon)?.name)}</summary><div class="form-grid"><label>Klasse ${select('armyBenchEntry-'+i+'-role',M.roles,a.role)}</label><label>Waffe ${select('armyBenchEntry-'+i+'-weapon',[['class','Passend zur Klasse'],...M.weaponDefs.map(w=>[w.id,w.name])],a.weapon)}</label><label>Rüstung ${select('armyBenchEntry-'+i+'-armor',[['auto','Passend zur Klasse'],['none','Keine'],['leather','Leder'],['medium','Verstärkt'],['metal','Metall']],a.armor)}</label><label>Schild ${select('armyBenchEntry-'+i+'-shield',[['auto','Passend zur Klasse'],['none','Keiner'],...M.shieldDefs.map(d=>[d.id,d.name])],a.shield)}</label><label>Qualität ${select('armyBenchEntry-'+i+'-quality',M.gearQuality.map((n,q)=>[q,n]),a.quality)}</label></div></details>`).join('')}</div><section class="box"><h2>${c.count0} gegen ${c.count1}</h2>${B('BENCHMARK STARTEN','army:benchstart')}<p>Höchstens 100 je Team, 120 Simulationssekunden. Formationen, Waffen, Klassen und Anführer sind für beide Teams separat einstellbar.</p></section>${M.benchmarkResults.map(r=>`<section class="box"><h3>${r.config.count0||r.config.count} gegen ${r.config.count1||r.config.count} · ${r.winner<0?'Zeitlimit / beendet':r.winner?'Rot gewinnt':'Blau gewinnt'}</h3><p>${r.time.toFixed(1)} Sekunden · ${r.fps.toFixed(1)} FPS · ${r.stepMs.toFixed(2)} ms je Simulationsschritt · Seed ${r.config.seed}</p>${r.teams.map((x,t)=>`<p>${t?'Rot':'Blau'}: ${x.alive} kampffähig, ${Math.round(x.damage)} Schaden, ${x.attacks} Angriffe</p>`).join('')}${benchmarkBreakdown(r)}</section>`).join('')}`;}
function lineup(){const gs=[...M.selectedTeam()],leader=gs.find(g=>g.id===A.plan().leader);if(leader){gs.splice(gs.indexOf(leader),1);gs.splice(Math.floor(gs.length/2),0,leader);}return `<section class="box team-showcase"><h2>${e(A.plan().name)} · Mannschaft</h2><p>Gladiator antippen, um ihn auszurüsten. Kämpfer können in mehreren Teams stehen; Zustand und Ausrüstung bleiben gemeinsam.</p><div class="lineup-scroll"><div class="team-lineup">${gs.map((g,i)=>`<button class="lineup-fighter ${g===leader?'leader':''}" data-action="loadout:${g.id}" aria-label="Ausrüstung von ${e(g.name)}"><span>${g===leader?'★ ANFÜHRER':e(g.role)}</span><canvas data-teamfigure="${g.id}" data-hero="${g===leader?'1':'0'}" data-pose="${i}"></canvas><strong>${e(g.name)}</strong></button>`).join('')||'<p>Noch keine Gladiatoren aufgestellt.</p>'}</div></div></section>`;}
document.addEventListener('dragstart',ev=>{const el=ev.target.closest('[data-troop-drag]');if(el)ev.dataTransfer.setData('text/plain',el.dataset.troopDrag);});
document.addEventListener('dragover',ev=>{if(ev.target.closest('[data-troop-slot]'))ev.preventDefault();});
document.addEventListener('drop',ev=>{const el=ev.target.closest('[data-troop-slot]');if(!el)return;ev.preventDefault();const id=ev.dataTransfer.getData('text/plain');if(S.roster.some(g=>g.id===id)){A.setMember(+el.dataset.troopSlot,id);render();}});
M.paintTeamLineup=()=>{for(const c of document.querySelectorAll('[data-teamfigure]')){const g=S.roster.find(g=>g.id===c.dataset.teamfigure);if(g)M.renderTeamFigure(c,g,c.dataset.hero==='1',+c.dataset.pose);}};
let scoutObserver=null;const paintLineup=M.paintTeamLineup;M.paintTeamLineup=()=>{paintLineup?.();scoutObserver?.disconnect();const draw=c=>{const g=S.roster.find(g=>g.id===c.dataset.scoutfigure);if(g)M.renderTeamFigure(c,g,false);};const canvases=document.querySelectorAll('[data-scoutfigure]');if(typeof IntersectionObserver==='undefined'){for(const c of canvases)draw(c);return;}scoutObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){draw(entry.target);scoutObserver.unobserve(entry.target);}},{rootMargin:'100px'});for(const c of canvases)scoutObserver.observe(c);};
function needsPanel(){if(!M.selectedTeam().length)return `<section class="box"><h2>Ausrüstungscheck</h2><p>Stelle zuerst ein Team zusammen. Danach siehst du hier genau, welche Ausrüstung fehlt.</p>${B('Team zusammenstellen','nav:team')}</section>`;const n=A.equipmentNeeds(),roles=M.roles.map(role=>({role,n:M.selectedTeam().filter(g=>g.role===role).length}));return `<section class="box supply-panel"><h2>Ausrüstungscheck · ${e(A.plan().name)}</h2><p>${roles.map(r=>r.n+' '+r.role).join(' · ')}</p><details><summary>So arbeitet dein Team zusammen</summary><p>Soldaten binden Gegner. Assassinen nutzen diese Ablenkung für Flankenangriffe. Fernkämpfer entlasten die Front und schießen wirkungsvoller auf gebundene Gegner. Unterstützung wirkt nur durch nahe, kampffähige Mitstreiter mit passender Waffe; Teamwork und Taktik bestimmen ihre Stärke.</p><p>${M.selectedTeam().length<3?'Bei kleinen Teams sind nicht alle Klassen erforderlich.':roles.every(r=>r.n)?'Alle drei Aufgaben sind besetzt. Achte auf passende Waffen und eine zusammenhängende Formation.':'Noch nicht vertreten: '+roles.filter(r=>!r.n).map(r=>r.role).join(', ')+'. Ergänzen kann helfen; Reinklassenteams bleiben spielbar.'}</p></details><p>${n.missing?'<strong>'+n.missing+' wichtige Lücken</strong>':'✓ Waffen geprüft · Munition automatisch bereit'} · ${n.assign} aus dem Lager zuweisbar · ${n.buy} Beschaffungen · ${n.repair} Reparaturen</p><p class="tiny">Rüstung und Schilde sind Empfehlungen, keine Einsatzpflicht. Ein Zweihänder benötigt keinen Schild. Lagerstücke werden pro Teamcheck nur einmal eingeplant; gesperrte Plätze bleiben gesperrt.</p>${n.rows.length?`<details><summary>Fehlende Ausrüstung & Empfehlungen (${n.rows.length})</summary><div class="supply-list">${[...n.rows].sort((a,b)=>Number(b.required)-Number(a.required)).map(r=>`<div class="supply-row"><div><strong>${e(r.name||'Teamvorrat')}</strong><span>${e(r.label)} ${r.locked?'🔒':''}</span><small>${r.status==='assign'?'Im Lager: '+e(r.available):r.status==='repair'?'In der Schmiede reparieren':r.required?'Noch beschaffen · wichtig':'Noch beschaffen · Empfehlung'}</small></div>${B(r.status==='assign'?'Zuweisen':r.status==='repair'?'Schmiede':'Waffenkammer',r.status==='assign'?'loadout:'+r.id:r.status==='repair'?'nav:forge':'nav:equipment')}</div>`).join('')}</div></details>`:'<p>Dein Team ist vollständig ausgestattet.</p>'}<div class="toolbar">${B('Team automatisch ausrüsten','army:equipteam')}${B('Waffenkammer öffnen','nav:equipment')}</div></section>`;}
const menuGroups=[{name:'Ludus',icon:'⌂',home:'home',pages:[['home','Ludus'],['profiles','Spielstände'],['stats','Statistik'],['options','Optionen']]},{name:'Arena',icon:'⚔',home:'arena',pages:[['arena','Gegnerische Schulen'],['benchmark','Testkämpfe'],['report','Kampfbericht']]},{name:'Kader',icon:'♜',home:'team',pages:[['team','Truppenplatz'],['gladiators','Kaserne'],['scout','Talentscout · IST / SOLL'],['market','Rekrutieren'],['medic','Krankenhaus'],['training','Kampflernen']]},{name:'Ausrüstung',icon:'⚒',home:'equipment',pages:[['equipment','Waffenkammer'],['forge','Schmiede']]},{name:'Mehr',icon:'▥',home:'automation',pages:[['automation','Automatik'],['school','Trainer'],['household','Familien'],['offspring','Nachwuchs'],['fallen','Gefallene']]}];
function groupFor(page){return menuGroups.find(g=>g.pages.some(([id])=>id===page))||menuGroups[['detail','gladiators','attributes','mantles'].includes(page)?2:0];}
M.menuNav=page=>menuGroups.map(g=>`<button data-action="nav:${g.home}" class="${groupFor(page)===g?'active':''}" ${groupFor(page)===g?'aria-current="true"':''}><i>${g.icon}</i><span>${g.name}</span></button>`).join('');
function dashboard(){const p=A.plan(),ready=S.roster.filter(g=>A.ready(g,true)).length,injured=S.roster.filter(g=>M.health(g)<99).length;return head('Dein Ludus','Aufstellen, ausrüsten, kämpfen. Du entscheidest, wann ein neuer Tag beginnt.')+`<div class="dashboard-stats"><div><strong>${S.roster.length}</strong><span>Gladiatoren</span></div><div><strong>${ready}</strong><span>Einsatzbereit</span></div><div><strong>${injured}</strong><span>Verletzt</span></div><div><strong>${S.teams.length}</strong><span>Teams</span></div></div><section class="box dashboard-team"><span class="tag">AKTIVES TEAM · ${p.size} GEGEN ${p.size}</span><h2>${e(p.name)}</h2><p>${e(M.validateTeam('challenge')||'Dein Team ist bereit für die Arena.')}</p><div class="toolbar">${B('Zur Arena','nav:arena')}${B('Team einsatzbereit machen','army:ready')}${B('Aufstellung bearbeiten','nav:team')}</div></section>`;}
M.schoolPage=page=>({market:recruitPage,scout:scoutPage,gladiators:rosterOverview,team:teamPage,home:dashboard,arena:armyArena,medic:hospitalPage,automation:automationPage,offspring:offspringPage,forge:workshopPage,benchmark:benchmarkPage}[page]?.());
M.armyProfile=g=>`<section class="box"><h2>Klasse, Einsatz & Sperren</h2><p>${e(g.role)} · ${e(A.teamOf(g.id)||'Ohne Team')}<br>${g.reserve?'Reservist':'Aktiver Kader'} · ${g.available===false?'Geschont':'Freigegeben'}</p>${B('VERWALTEN & SPERREN','army:person:'+g.id)}</section>`;
M.schoolDecorate=(page,html)=>{const group=groupFor(page);const tabs=`<nav class="section-tabs" aria-label="${group.name}">${group.pages.map(([id,name])=>`<button data-action="nav:${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${name}</button>`).join('')}</nav>`;if(page==='equipment')html=html+ammoPanel();return `<label class="mobile-section">${group.name}${select('mobileSection',group.pages.some(([id])=>id===page)?group.pages:[['','Ansicht wählen'],...group.pages],group.pages.some(([id])=>id===page)?page:'')}</label>`+tabs+html;};
M.schoolClick=action=>{const [prefix,a,b,c]=action.split(':');if(prefix==='nav'){if(a==='team'){teamOpen=true;troopSize=A.plan()?.size||3;}M.ui.close();pageNo=0;return false;}if(prefix==='scoutmarket'){M.ui.click('nav:scout');return true;}if(['rest','rest3','familyrest','familyrestconfirm'].includes(prefix)){if(S.battle){notify('Während des Kampfes nicht möglich.');return true;}notify(A.nextDay());render();dayReport();return true;}if(prefix==='teamtoggle'){const list=S.teams[S.teamIndex],i=list.indexOf(a);if(i>=0)list.splice(i,1);else if(list.filter(Boolean).length<A.plan().size)list.push(a);A.savePlan();render();return true;}if(prefix==='teamindex'){teamOpen=true;A.activateTeam(+a);troopSize=A.plan().size;render();return true;}if(prefix==='hiresmith'){notify(A.hireWorkshop());render();return true;}if(prefix!=='army')return false;if(S.battle){notify('Beende zuerst den Kampf.');return true;}let message='';
 if(a==='troopsize'){troopSize=+b;troopSlot=0;pageNo=0;render();return true;}
 if(a==='troopslot'){troopSlot=+b;render();return true;}
 if(a==='troopadd'){A.setMember(troopSlot,b);const next=S.teams[S.teamIndex].findIndex(id=>!id);troopSlot=next>=0?next:Math.min(S.teams[S.teamIndex].length,A.plan().size-1);render();return true;}
 if(a==='troopremove'){A.setMember(+b,'');if(!S.teams[S.teamIndex].includes(A.plan().leader))A.plan().leader=null;M.persist();render();return true;}
 if(a==='troopleader'){A.plan().leader=b;M.persist();render();return true;}
 if(a==='scoutreset'){scoutClass=scoutWeapon=filter=origin=teamFilter='all';query='';order='combat';pageNo=0;render();return true;}if(a==='teamoverview'){teamOpen=false;render();return true;}if(a==='openteam'){A.activateTeam(+b);troopSize=A.plan().size;teamOpen=true;render();return true;}if(a==='newsize'){troopSize=+b;A.newTeam(troopSize+'er-Gruppe',troopSize);teamOpen=true;render();return true;} if(a==='deleteteam'){modal('Team löschen?',`<p>Die Aufstellung <strong>${e(A.plan().name)}</strong> wird gelöscht. Alle Gladiatoren, Gegenstände und anderen Teams bleiben erhalten.${S.teams.length===1?' Für die letzte Aufstellung wird ein leeres Team angelegt.':''}</p>`,B('TEAM LÖSCHEN','army:confirmdelete:'+S.teamIndex));return true;}if(a==='confirmdelete'){message=A.deleteTeam(+b);M.ui.close();}if(a==='difficulty'){difficultyBand=Math.max(0,Math.min(9,Number(b)));render();return true;}if(a==='page'){pageNo=Math.max(0,pageNo+Number(b));render();return true;}if(a==='workpage'){workPage=Math.max(0,workPage+Number(b));render();return true;}if(a==='person'){personDialog(b);return true;}if(a==='quick'){scoutClass=b;scoutWeapon='all';order=c;filter='all';pageNo=0;render();return true;}if(a==='filter'){filter=b;pageNo=0;order='potential';M.ui.click('nav:scout');return true;}
 if(a==='recruit'||a==='recruit10'){const amount=a==='recruit10'?10:Math.floor(Number($('armyRecruitCount').value));if(!Number.isFinite(amount)||amount<1||amount>Math.floor(S.gold/100)){notify('Wähle eine bezahlbare Anzahl.');return true;}lastRecruits=A.recruitMany(amount).map(g=>g.id);message=lastRecruits.length+' Rekruten für '+lastRecruits.length*100+' Gold aufgenommen.';}
 if(a==='classes'){A.autoClasses();message='Klassen zugewiesen. Gesperrte Klassen beibehalten.';}if(a==='equipall')message=A.autoEquip(S.roster,S.army.equipPriority||'balanced');if(a==='equipteam')message=A.autoEquip(M.selectedTeam(),S.army.equipPriority||'balanced');if(a==='autoteam')message=A.autoTeam(A.plan().goal||'balanced');if(a==='replace')message=A.replaceInjured();if(a==='ready')message=A.prepareTeam();
 if(a==='newteam'){teamOpen=true;troopSize=3;A.newTeam('3er-Gruppe',3);message='Neues Team angelegt.';}if(a==='saveplan'){A.savePlan();message='Klassen, Taktik und Ausrüstung gespeichert.';}if(a==='restoreplan'){const p=A.plan();let skipped=0;for(const g of M.selectedTeam()){if(!g.locks.class&&p.classes[g.id])g.role=p.classes[g.id];const eq=p.loadouts[g.id];if(!eq)continue;for(const k of A.slots){if(g.locks[k])continue;const id=['weapon','secondary','shield'].includes(k)?eq[k]:eq.armor[k];if(id&&M.equippedBy(id)&&M.equippedBy(id).id!==g.id){skipped++;continue;}if(!id||M.inventoryItem(id))A.putSlot(g,k,id);}}message='Teamvorlage geladen. '+skipped+' belegte Gegenstände nicht übernommen; Sperren beachtet.';}
 if(a==='reserve'){const id=$('armyReserve').value,p=A.plan();if(id){if(p.reserves.includes(id))p.reserves=p.reserves.filter(x=>x!==id);else p.reserves.push(id);}message='Reservepool gespeichert.';}
 if(a==='rules'){Object.assign(S.army.rules,b==='careful'?{health:90,energy:85,grade:1,bleed:0,fractures:false,internal:false}:b==='aggressive'?{health:45,energy:25,grade:4,bleed:5,fractures:true,internal:false}:{health:75,energy:60,grade:2,bleed:0,fractures:false,internal:false});}
 if(a==='challenge'){const x=S.army.challenges.find(x=>x.id===b);modal(x.name,`<p>${x.size} gegen ${x.size}. Einsatz ${x.fee} Gold, Sieg ${x.reward} Gold. Verletzungen und Tod bleiben dauerhaft.</p><p>${e(M.validateTeam('challenge')||'Team einsatzbereit.')}</p>`,B('KAMPF STARTEN','army:challengego:'+b,!!M.validateTeam('challenge')));return true;}if(a==='challengego'){M.ui.close();message=A.beginChallenge(b);if(S.battle)return true;}
 if(a==='leaguefight'){modal('Ligakampf',`<p>${A.plan().size} gegen ${A.plan().size} · ${e(M.validateTeam('league')||'Team bereit')}</p>`,B('STARTEN','army:leaguego',!!M.validateTeam('league')));return true;}if(a==='leaguego'){M.ui.close();message=M.beginFight('league');if(S.battle)return true;}
 if(a==='ammo')message=A.buyAmmo(b,100);if(a==='treatall'){const patients=S.roster.filter(g=>Object.values(g.body).some(p=>p.hp<100-p.chronic||p.bleed));const cost=patients.reduce((n,g)=>n+M.medicalCost(g,1),0);modal('Sammelbehandlung',`<p>${patients.length} Gladiatoren · ${f(cost)} Gold. Kein Tag vergeht.</p>`,B('BEHANDLUNG BESTÄTIGEN','army:treatconfirm',S.gold<cost));return true;}if(a==='treatconfirm'){M.ui.close();let n=0;M.batchSaving=true;try{for(const g of S.roster)if(Object.values(g.body).some(p=>p.hp<100-p.chronic||p.bleed)&&S.gold>=M.medicalCost(g,1)){M.treat(g.id,1);n++;}}finally{M.batchSaving=false;}message=n+' Gladiatoren behandelt.';}
 if(a==='childprofile'){const child=S.children.find(x=>x.id===b),g=child.template;modal(g.name,`<p>Vater: ${e(child.parents.father.name)} · Mutter: ${e(child.parents.mother.name)}</p><p>${g.height} cm · ${g.weight} kg · ${e(g.origin)}</p><div class="stats-grid">${Object.keys(M.stats).map(k=>`<div class="stat"><span>${M.stats[k]}</span><b>${g.stats[k].toFixed(1)} / ${g.caps.stats[k]}</b></div>`).join('')}</div><h3>Waffenbegabung</h3>${M.weaponDefs.map(w=>`<p>${w.name}: ${g.mastery[w.id].toFixed(1)} / ${g.caps.weapons[w.id]}</p>`).join('')}`);return true;}
 if(a==='hiresmith')message=A.hireWorkshop();if(a==='craft'){const [kind,def]=$('armyCraftDef').value.split('/'),q=+$('armyCraftQ').value,material=$('armyCraftMaterial').value;message=M.craft(kind,def,q,material);}if(a==='repairall'){const damaged=S.inventory.filter(i=>M.repairCost(i)>0),cost=damaged.reduce((n,i)=>n+M.repairCost(i),0);modal('Alles reparieren?',`<p>${damaged.length} Gegenstände · ${f(cost)} Gold.</p>`,B('REPARIEREN','army:repairconfirm',S.gold<cost));return true;}if(a==='repairconfirm'){M.ui.close();M.batchSaving=true;try{for(const i of S.inventory)if(M.repairCost(i)>0&&S.gold>=M.repairCost(i))M.forge(i.id,'repair');}finally{M.batchSaving=false;}message='Reparaturen abgeschlossen.';}if(a==='improve')message=A.workshopImprove(b,c);
 if(a==='bulkgear'){modal('Ausrüstung mehrfach kaufen',`<label>Gegenstand ${select('armyBulkDef',M.forgeCategories.map(c=>[c.key,c.name]),'weapon/gladius')}</label><label>Qualität ${select('armyBulkQ',M.gearQuality.map((n,i)=>[i,n]),1)}</label><label>Material ${select('armyBulkMaterial',[['leather','Leder'],['medium','Verstärkt'],['metal','Metall']],'metal')}</label><label>Anzahl ${input('armyBulkN',10,1,1000)}</label>`,B('KOSTEN ANZEIGEN','army:bulkquote'));return true;}if(a==='bulkquote'){S.army.bulk={key:$('armyBulkDef').value,q:+$('armyBulkQ').value,material:$('armyBulkMaterial').value,n:Cint($('armyBulkN').value,1,1000)};const [k,d]=S.army.bulk.key.split('/'),cost=M.itemPrice(k,d,S.army.bulk.q)*S.army.bulk.n;modal('Massenkauf bestätigen',`<p>${S.army.bulk.n} Teile · ${f(cost)} Gold</p>`,B('KAUFEN','army:bulkbuy',S.gold<cost));return true;}if(a==='bulkbuy'){const x=S.army.bulk,[k,d]=x.key.split('/');M.ui.close();M.batchSaving=true;try{for(let i=0;i<x.n;i++)M.buyItem(k,d,x.q,x.material);}finally{M.batchSaving=false;}message=x.n+' Gegenstände gekauft.';}
 if(a==='benchpage'){benchOffset=Math.max(0,Math.min(Math.floor((ensureBench()['count'+benchSide]-1)/20)*20,benchOffset+Number(b)*20));render();return true;}if(a==='benchside'){benchOffset=0;benchSide=+b;render();return true;}if(a==='benchmix'){benchOffset=0;const c=ensureBench(),counts=[$('armyBenchSoldiers').value,$('armyBenchAssassins').value,$('armyBenchRanged').value].map(x=>Cint(x,0,100)),n=counts.reduce((a,b)=>a+b,0);if(!n||n>100){notify('Insgesamt 1 bis 100 Kämpfer pro Team wählen.');return true;}c['count'+benchSide]=n;let i=0;counts.forEach((n,r)=>{for(let j=0;j<n;j++)c.entries[benchSide][i++]={role:M.roles[r],weapon:'class',armor:'auto',shield:'auto',quality:2};});}if(a==='benchstart'){const c=ensureBench();c.count=Math.max(c.count0,c.count1);message=M.startBenchmark(c);if(S.battle)return true;}
 persist();render();if(message)notify(message);return true;
};
function Cint(x,min,max){return M.clamp(Math.floor(Number(x)||0),min,max);}
M.schoolChange=ev=>{const id=ev.target.id,v=ev.target.type==='checkbox'?ev.target.checked:ev.target.value;if(!id.startsWith('army'))return false;if(S.battle)return true;let refresh=false;
 if(id==='armyMode')S.army.mode=v;if(id==='armyEquipPriority')S.army.equipPriority=v;const rec={armyRecruitEnabled:'enabled',armyRecruitPerDay:'perDay',armyRecruitMinGold:'minGold',armyRecruitTarget:'target',armyRecruitReserves:'reserves'};if(rec[id])S.army.recruit[rec[id]]=typeof v==='boolean'?v:Cint(v,0,100000);
 if(id.startsWith('armyAuto-'))S.army.auto[id.slice(9)]=v;if(id.startsWith('armyBodyRule-')){const part=id.slice(13);S.army.rules.blockParts??=[];S.army.rules.blockParts=S.army.rules.blockParts.filter(x=>x!==part);if(v)S.army.rules.blockParts.push(part);}if(id.startsWith('armyRule-'))S.army.rules[id.slice(9)]=typeof v==='boolean'?v:Cint(v,0,id.endsWith('grade')?5:100);
 if(id==='troopClass'){troopClass=v;pageNo=0;render();return true;}if(id==='troopQuery'){troopQuery=v;pageNo=0;render();return true;}if(id==='armyTeam'){A.activateTeam(+v);refresh=true;}if(id==='armyTeamName')A.plan().name=String(v).slice(0,40)||'Team';if(id==='armyTeamSize'){const other=S.teamPlans.findIndex(p=>p.size===+v);if(other>=0&&other!==S.teamIndex){A.activateTeam(other);troopSize=+v;render();return true;}const size=+v,team=S.teams[S.teamIndex];if(team.slice(size).some(id=>S.roster.find(g=>g.id===id)?.locks.team)){notify('Entsperre zuerst die betroffenen Teamplätze.');render();return true;}A.plan().size=size;team.length=Math.min(team.length,size);refresh=true;}if(id==='armyTeamGoal')A.plan().goal=v;if(id==='armyLeader'){A.plan().leader=v||null;refresh=true;}if(id==='armyLeaderLock')A.plan().leaderLocked=!!v;if(id.startsWith('armyMember-')){A.setMember(+id.split('-')[1],v);refresh=true;}if(id.startsWith('armyTactic-')){S.tactics[id.slice(11)]=v;A.savePlan();}
 const fields=[['armyPersonRole-','role'],['armyAvailable-','available'],['armyReserveFlag-','reserve'],['armyTrain-','trainingWeapon'],['armyAmmo-','ammoLoad']];for(const [prefix,key]of fields)if(id.startsWith(prefix)){const g=S.roster.find(g=>g.id===id.slice(prefix.length));if(g)g[key]=key==='ammoLoad'?Cint(v,0,M.gear(g,'weapon')?.def==='crossbow'?8:12):v;}
 if(id.startsWith('armyLock-')){const rest=id.slice(9),split=rest.lastIndexOf('-'),gid=rest.slice(0,split),key=rest.slice(split+1),g=S.roster.find(g=>g.id===gid);if(g)g.locks[key]=!!v;}
 if(id==='armyScoutClass'){scoutClass=v;if(!scoutWeapons().some(w=>w.id===scoutWeapon))scoutWeapon='all';refresh=true;}if(id==='armyScoutWeapon'){scoutWeapon=v;refresh=true;}if(id==='armyQuery'){query=v;refresh=true;}if(id==='armyOrder'||id==='armyAdvancedOrder'){order=v;refresh=true;}if(id==='armyFilter'){filter=v;refresh=true;}if(id==='armyOrigin'){origin=v;refresh=true;}if(id==='armyTeamFilter'){teamFilter=v;refresh=true;}if(id==='armyHospitalBand'){hospitalBand=v;refresh=true;}
 if(id==='armyCraftDef')S.army.craftKey=v;if(id==='armyCraftQ')S.army.craftQ=+v;if(id==='armyCraftMaterial')S.army.craftMaterial=v;
 const c=ensureBench();if(id==='armyBenchCount'){benchOffset=0;c['count'+benchSide]=Cint(v,1,100);refresh=true;}if(id==='armyBenchSeed')c.seed=Cint(v,1,4294967295);if(id==='armyBenchLeague')c.league=Cint(v,0,6);if(id==='armyBenchLeader')c.leaderIndices[benchSide]=+v;if(id.startsWith('armyBenchTactic-'))c.teamTactics[benchSide][id.slice(16)]=v;if(id.startsWith('armyBenchEntry-')){const [i,k]=id.slice(15).split('-');c.entries[benchSide][+i][k]=k==='quality'?+v:v;if(k==='role')refresh=true;}
 persist();if(refresh){pageNo=0;render();}return true;};
M.armyBattleHUD=()=>false;
M.classDamageTotals=b=>{const rows=[Object.fromEntries(M.roles.map(r=>[r,0])),Object.fromEntries(M.roles.map(r=>[r,0]))];for(const a of b.actors)if(rows[a.team]&&Object.hasOwn(rows[a.team],a.g.role))rows[a.team][a.g.role]+=Number.isFinite(a.damage)?a.damage:0;return rows;};
M.teamHeads=b=>{const top=$('battleTop'),key=b.id+':'+b.actors.map(a=>a.id).join('|');top.classList.add('portrait-sides');if(top.dataset.headKey!==key){top.dataset.headKey=key;top.innerHTML=[0,1].map(t=>`<section class="head-side side-${t}"><h3>${e(t?b.opponent:b.benchmark?'BLAU':S.schoolName)}</h3><div class="head-roster">${b.actors.filter(a=>a.team===t).map(a=>`<button id="head-${a.id}" class="combat-head" data-action="inspect:${a.id}" title="${e(a.g.name)}"><canvas id="headpic-${a.id}"></canvas><span>${e(a.g.name.split(' ')[0])}</span><small id="headstate-${a.id}"></small></button>`).join('')}</div><div class="class-damage-live" aria-label="Schaden nach Klasse"><span>SCHADEN</span>${M.roles.map((role,i)=>`<span>${e(role)} <b id="class-dmg-${t}-${i}">0</b></span>`).join('')}</div></section>`).join('')+`<div class="head-clock"><strong id="fightClock"></strong>${b.benchmark?'<div id="benchLive"></div>':''}</div>`;}const totals=M.classDamageTotals(b);for(const team of [0,1])M.roles.forEach((role,i)=>{const el=$('class-dmg-'+team+'-'+i),value=Math.round(totals[team][role]).toLocaleString('de-DE');if(el&&el.textContent!==value)el.textContent=value;});const clock=$('fightClock');if(clock)clock.textContent=Math.floor(b.time/60)+':'+String(Math.floor(b.time%60)).padStart(2,'0');for(const a of b.actors){const el=$('head-'+a.id),c=$('headpic-'+a.id),st=$('headstate-'+a.id);if(!el||!c)continue;const hero=b.leaders?.[a.team]===a.id,state=a.g.dead?'Gefallen':a.down?'K.O.':a.surrendered?'Aufgabe':a.fallTimer>0?'Am Boden':a.kneeTimer>0?'Auf den Knien':a.state==='reload'?'Lädt':a.g.blood<55?'Blutung':a.energy<20?'Erschöpft':'';const cls='combat-head '+(hero?'hero ':'')+(a.g.dead?'dead ':a.down?'down ':''),tip=a.g.name+(hero?' · Anführer':'')+(state?' · '+state:'');if(el.className!==cls)el.className=cls;if(el.title!==tip)el.title=tip;if(st&&st.textContent!==state)st.textContent=state;const paintKey=[M.expression(a),a.g.dead,a.g.body.head.missing,M.armorItems(a.g).find(i=>i.def==='helm')?.id].join(':');const bounds=c.dataset.paintKey!==paintKey&&b.actors.length>60?c.getBoundingClientRect():null;if(c.dataset.paintKey!==paintKey&&(!bounds||(bounds.right>0&&bounds.left<innerWidth&&bounds.bottom>0&&bounds.top<innerHeight))){const portraitG={...a.g,dead:false,bisected:false};M.renderPortrait(c,portraitG,{...a,down:false,fallTimer:0,neckFinishTimer:0,state:a.g.dead?'idle':a.state});c.dataset.paintKey=paintKey;}}};

M.ui.render();
})();
